package com.aditya.chat; import com.aditya.chat.dto.*;import com.aditya.chat.entity.AppUser;import com.aditya.chat.repository.UserRepository;import com.aditya.chat.security.JwtService;import com.aditya.chat.service.AuthService;import org.junit.jupiter.api.Test;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import java.util.Optional;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*; class AuthServiceTest{@Test void loginWorks(){UserRepository r=mock(UserRepository.class);var e=new BCryptPasswordEncoder();var j=new JwtService("12345678901234567890123456789012");when(r.findByUsername("aditya")).thenReturn(Optional.of(new AppUser("aditya",e.encode("secret123"))));var s=new AuthService(r,e,j);var x=s.login(new LoginRequest("aditya","secret123"));assertEquals("aditya",x.username());assertNotNull(x.token());}}
